(() => {
  // ดึงข้อมูลจาก AI Agent
  let data = $json.output;

  // แปลง String เป็น Object กรณี AI ส่งผลลัพธ์เป็น JSON String
  if (typeof data === 'string') {
    try {
      data = JSON.parse(data);
    } catch (e) {
      data = {};
    }
  }

  if (data && data.output && typeof data.output === 'object') {
    data = data.output;
  }

  // ดึงค่าภาพรวม ข่าวสาร และบทสรุปเชิงธุรกิจจาก AI โดยตรง
  const overview = data?.overview || data?.executive_summary || "ภาพรวมข่าวสารสำคัญในรอบวัน";
  const newsList = Array.isArray(data?.news) ? data.news : (Array.isArray(data?.topics) ? data.topics : []);
  const decisionSummary = data?.decision_summary || data?.business_impact || data?.business_decision_summary || null;

  const userQuery = $('Webhook').item?.json?.body?.events?.[0]?.message?.text || "ข่าวประจำวัน";
  const token = $('Webhook').item?.json?.body?.events?.[0]?.replyToken || "";

  // ประกอบกล่องเนื้อหา Body
  const bodyContents = [
    {
      type: "box",
      layout: "vertical",
      backgroundColor: "#F1F5F9",
      paddingAll: "md",
      cornerRadius: "md",
      contents: [
        {
          type: "text",
          text: "🔹 ภาพรวมประจำวัน",
          weight: "bold",
          size: "xs",
          color: "#334155"
        },
        {
          type: "text",
          text: overview,
          size: "xs",
          color: "#475569",
          wrap: true,
          margin: "xs"
        }
      ]
    },
    {
      type: "separator"
    },
    ...newsList.slice(0, 3).map((item, index) => {
      return {
        type: "box",
        layout: "vertical",
        spacing: "xs",
        margin: "sm",
        contents: [
          {
            type: "text",
            text: `${index + 1}. ${item.title || 'หัวข้อข่าว'}`,
            weight: "bold",
            size: "sm",
            color: "#0F172A",
            wrap: true
          },
          {
            type: "text",
            text: item.summary || item.description || "ไม่มีเนื้อหาโดยย่อ",
            size: "xs",
            color: "#64748B",
            wrap: true
          },
          {
            type: "button",
            style: "link",
            height: "sm",
            action: {
              type: "uri",
              label: "🔗 อ่านต่อฉบับเต็ม",
              uri: (item.link || item.reference_url || "https://news.google.com").substring(0, 990)
            }
          }
        ]
      };
    })
  ];

  // ถ้า AI ส่ง decision_summary มา ให้ต่อกล่องสีฟ้าท้ายการ์ด
  if (decisionSummary) {
    bodyContents.push(
      {
        type: "separator",
        margin: "md"
      },
      {
        type: "box",
        layout: "vertical",
        backgroundColor: "#EFF6FF",
        paddingAll: "md",
        cornerRadius: "md",
        margin: "sm",
        contents: [
          {
            type: "text",
            text: "💡 สรุปเพื่อสนับสนุนการตัดสินใจทางธุรกิจ",
            weight: "bold",
            size: "xs",
            color: "#1D4ED8"
          },
          {
            type: "text",
            text: decisionSummary,
            size: "xs",
            color: "#1E293B",
            wrap: true,
            margin: "xs"
          }
        ]
      }
    );
  }

  return JSON.stringify({
    replyToken: token,
    messages: [
      {
        type: "flex",
        altText: "สรุปข่าวสำคัญประจำวัน",
        contents: {
          type: "bubble",
          header: {
            type: "box",
            layout: "vertical",
            backgroundColor: "#0F172A",
            paddingAll: "lg",
            contents: [
              {
                type: "text",
                text: "📊 DAILY NEWS BRIEF",
                weight: "bold",
                color: "#38BDF8",
                size: "xs"
              },
              {
                type: "text",
                text: "สรุป" + userQuery,
                weight: "bold",
                color: "#FFFFFF",
                size: "lg",
                margin: "xs"
              }
            ]
          },
          body: {
            type: "box",
            layout: "vertical",
            spacing: "md",
            contents: bodyContents
          }
        }
      }
    ]
  });
})()
}}

