(() => {
  // 1. ดึงและแกะโครงสร้าง JSON จาก AI Agent แบบ Recursive Unnesting
  let data = $('AI Agent2').item?.json?.output;

  // แกะกรณีข้อมูลเป็น String ติดกัน (รองรับ String ที่ครอบซ้อน 2 ชั้น)
  for (let i = 0; i < 3; i++) {
    if (typeof data === 'string') {
      try {
        data = JSON.parse(data);
      } catch (e) {
        break;
      }
    }
    if (data && typeof data === 'object' && data.output) {
      data = data.output;
    }
  }

  // 2. ดึงค่าสรุปภาพรวมและรายการข่าว
  const summary = (data && data.executive_summary) 
    ? data.executive_summary 
    : "สรุปประเด็นข่าวสารสำคัญล่าสุดที่เกี่ยวข้อง";

  // ดึง news ออกมาให้ได้ แม้จะหลุดไปอยู่ในคีย์อื่น เช่น topics
  let newsList = [];
  if (data && Array.isArray(data.news)) {
    newsList = data.news;
  } else if (data && Array.isArray(data.topics)) {
    newsList = data.topics;
  }

  const queryText = $('Webhook').item?.json?.body?.events?.[0]?.message?.text || "ข่าวบันเทิง";

  // 3. ประกอบกล่องแสดงข่าวสาร (newsBoxes)
  const newsBoxes = [];

  newsList.slice(0, 3).forEach((item, idx) => {
    // ดึงหัวข้อและเนื้อหาย่อ
    const newsTitle = typeof item === 'string' ? item : (item.title || `ข่าวที่ ${idx + 1}`);
    const newsDesc = typeof item === 'object' ? (item.summary || item.description || '') : '';
    const readUrl = typeof item === 'object' ? (item.reference_url || item.url || item.link) : null;

    // กล่องข้อความ
    newsBoxes.push({
      type: "box",
      layout: "vertical",
      margin: idx === 0 ? "none" : "lg",
      spacing: "xs",
      contents: [
        {
          type: "text",
          text: `${idx + 1}. ${newsTitle}`,
          weight: "bold",
          size: "sm",
          color: "#0F172A",
          wrap: true
        },
        ...(newsDesc ? [{
          type: "text",
          text: newsDesc,
          size: "xs",
          color: "#475569",
          wrap: true,
          margin: "xs"
        }] : [])
      ]
    });

    // ปุ่มกดอ่านต่อฉบับเต็ม (ถ้ามีลิงก์ URL)
    if (readUrl && typeof readUrl === 'string' && readUrl.startsWith('http')) {
      newsBoxes.push({
        type: "button",
        style: "secondary",
        color: "#F1F5F9",
        height: "sm",
        margin: "sm",
        action: {
          type: "uri",
          label: "🔗 อ่านต่อฉบับเต็ม",
          uri: readUrl
        }
      });
    }

    // เส้นคั่นระหว่างข้อ
    if (idx < Math.min(newsList.length, 3) - 1) {
      newsBoxes.push({
        type: "separator",
        margin: "lg",
        color: "#E2E8F0"
      });
    }
  });

  // กรณีข่าวใน newsList ว่างเปล่า ให้แสดงข้อความแจ้งเตือนแทนการปล่อยการ์ดว่าง
  if (newsBoxes.length === 0) {
    newsBoxes.push({
      type: "text",
      text: "ไม่พบรายละเอียดข่าวเพิ่มเติมจากคำค้นหานี้ กรุณาลองระบุคำค้นหาใหม่อีกครั้ง",
      size: "xs",
      color: "#64748B",
      wrap: true
    });
  }

  // 4. บรรจุลงโครงสร้าง Flex Message
  return JSON.stringify({
    replyToken: $('Webhook').item.json.body.events[0].replyToken,
    messages: [
      {
        type: "flex",
        altText: `สรุป${queryText}`,
        contents: {
          type: "bubble",
          size: "mega",
          header: {
            type: "box",
            layout: "vertical",
            backgroundColor: "#0B132B",
            paddingAll: "xl",
            contents: [
              {
                type: "box",
                layout: "horizontal",
                spacing: "xs",
                contents: [
                  {
                    type: "text",
                    text: "📊",
                    size: "xs",
                    flex: 0
                  },
                  {
                    type: "text",
                    text: "DAILY NEWS BRIEF",
                    weight: "bold",
                    color: "#38BDF8",
                    size: "xs"
                  }
                ]
              },
              {
                type: "text",
                text: queryText.startsWith('สรุป') ? queryText : `สรุป${queryText}`,
                weight: "bold",
                color: "#FFFFFF",
                size: "xl",
                margin: "sm",
                wrap: true
              }
            ]
          },
          body: {
            type: "box",
            layout: "vertical",
            paddingAll: "xl",
            contents: [
              {
                type: "box",
                layout: "vertical",
                backgroundColor: "#F0F6FF",
                cornerRadius: "md",
                paddingAll: "md",
                margin: "none",
                contents: [
                  {
                    type: "text",
                    text: "🔹 ภาพรวมประจำวัน",
                    weight: "bold",
                    size: "xs",
                    color: "#0284C7"
                  },
                  {
                    type: "text",
                    text: summary,
                    size: "xs",
                    color: "#334155",
                    wrap: true,
                    margin: "xs"
                  }
                ]
              },
              {
                type: "separator",
                margin: "lg",
                color: "#E2E8F0"
              },
              ...newsBoxes
            ]
          }
        }
      }
    ]
  });
})()
}}

