(() => {

  // 1. ดึงข้อความดิบจาก AI Agent2

  let raw = $json.output;

  let text = "";

  let newsList = [];

  let overview = "";



  // กรณีที่ 1: ถ้าส่งมาเป็น JSON Object หรือ String JSON ให้ลอง parse ก่อน

  let parsed = null;

  try {

    if (typeof raw === 'object' && raw !== null) {

      parsed = raw;

    } else if (typeof raw === 'string' && (raw.trim().startsWith('{') || raw.trim().startsWith('['))) {

      parsed = JSON.parse(raw);

    }

  } catch (e) {

    parsed = null;

  }



  const data = parsed?.output || parsed;

  if (data && typeof data === 'object' && Array.isArray(data.news)) {

    overview = data.executive_summary || data.overview || "ภาพรวมประเด็นข่าวสำคัญล่าสุด";

    newsList = data.news.slice(0, 3).map(item => ({

      title: item.title,

      summary: item.summary,

      url: item.reference_url || item.link || item.url

    }));

  } else {

    // กรณีที่ 2: ถ้าส่งมาเป็นข้อความ Plain Text (แบบในภาพล่าสุด)

    text = (typeof raw === 'string' ? raw : JSON.stringify(raw))

      .replace(/\\n/g, '\n')

      .replace(/\\"/g, '"')

      .trim();



    // ดึงท่อนภาพรวมประจำวัน

    const overviewMatch = text.match(/(?:สรุปภาพรวม[^\n]*|ภาพรวม[^\n]*)\n*([\s\S]*?)(?=(?:หัวข้อ\s*[:：]|\d+\.\s*หัวข้อ|$))/i);

    if (overviewMatch) {

      overview = overviewMatch[1].trim();

    } else {

      overview = "สรุปประเด็นข่าวสารสำคัญล่าสุดที่เกี่ยวข้อง";

    }



    // ตัดแบ่งข่าวตามคำว่า "หัวข้อ:"

    const rawItems = text.split(/(?=(?:⚡\s*)?(?:[1-9]\.\s*)?หัวข้อ\s*[:：])/g)

      .filter(item => /หัวข้อ\s*[:：]/.test(item));



    rawItems.slice(0, 3).forEach((itemStr, idx) => {

      // ดึงหัวข้อ

      const titleMatch = itemStr.match(/หัวข้อ\s*[:：]\s*([^\n]+)/);

      // ดึงเนื้อหา

      const summaryMatch = itemStr.match(/เนื้อหา\s*[:：]\s*([\s\S]*?)(?=(?:ลิงก์|ที่มา|แหล่งที่มา)\s*[:：]|$)/);

      // ดึงลิงก์ URL

      const linkMatch = itemStr.match(/(https?:\/\/[^\s\)\n]+)/);



      newsList.push({

        title: titleMatch ? titleMatch[1].trim() : `ข่าวที่ ${idx + 1}`,

        summary: summaryMatch ? summaryMatch[1].trim() : "",

        url: linkMatch ? linkMatch[1].trim() : null

      });

    });

  }



  const userText = $('Webhook').item?.json?.body?.events?.[0]?.message?.text || "ข่าวด่วน";



  // 2. สร้างกล่องข่าวและปุ่มอ่านต่อฉบับเต็มทีละข่าว

  const newsContents = [];

  newsList.forEach((item, index) => {

    const singleNews = [

      {

        type: "text",

        text: `${index + 1}. ${item.title}`,

        weight: "bold",

        size: "sm",

        color: "#0F172A",

        wrap: true

      }

    ];



    if (item.summary) {

      singleNews.push({

        type: "text",

        text: item.summary,

        size: "xs",

        color: "#64748B",

        wrap: true,

        margin: "xs"

      });

    }



    if (item.url) {

      singleNews.push({

        type: "button",

        style: "link",

        height: "sm",

        action: {

          type: "uri",

          label: "🔗 อ่านต่อฉบับเต็ม",

          uri: item.url

        }

      });

    }



    newsContents.push({

      type: "box",

      layout: "vertical",

      spacing: "xs",

      margin: "md",

      contents: singleNews

    });

  });



  // 3. ประกอบโครงสร้าง Flex Message

  return JSON.stringify({

    replyToken: $('Webhook').item.json.body.events[0].replyToken,

    messages: [

      {

        type: "flex",

        altText: `สรุปข่าว: ${userText}`,

        contents: {

          type: "bubble",

          header: {

            type: "box",

            layout: "vertical",

            backgroundColor: "#0F172A",

            paddingAll: "lg",

            contents: [

              {

                type: "text",

                text: "📊 DAILY NEWS BRIEF",

                weight: "bold",

                color: "#38BDF8",

                size: "xs"

              },

              {

                type: "text",

                text: `สรุป${userText}`,

                weight: "bold",

                color: "#FFFFFF",

                size: "lg",

                margin: "xs",

                wrap: true

              }

            ]

          },

          body: {

            type: "box",

            layout: "vertical",

            spacing: "md",

            contents: [

              {

                type: "box",

                layout: "vertical",

                backgroundColor: "#F1F5F9",

                paddingAll: "md",

                cornerRadius: "md",

                contents: [

                  {

                    type: "text",

                    text: "🔹 ภาพรวมประจำวัน",

                    weight: "bold",

                    size: "xs",

                    color: "#334155"

                  },

                  {

                    type: "text",

                    text: overview,

                    size: "xs",

                    color: "#475569",

                    wrap: true,

                    margin: "xs"

                  }

                ]

              },

              {

                type: "separator"

              },

              ...(newsContents.length > 0 ? newsContents : [

                {

                  type: "text",

                  text: text || overview,

                  size: "sm",

                  color: "#0F172A",

                  wrap: true

                }

              ])

            ]

          }

        }

      }

    ]

  });

})()

}}

