// 3. กรองเอาเฉพาะข่าวที่ URL ไม่เคยอยู่ในชีต
const freshNews = incomingNews.filter(item => {
  const currentLink = item.json.link;
  return !usedUrls.some(usedUrl => usedUrl.includes(currentLink));
});

// ส่งเฉพาะข่าวใหม่ไปให้ AI สรุป (ถ้ากรองแล้วหมด ให้ส่งสำรองไป)
return freshNews.length > 0 ? freshNews : incomingNews.slice(0, 3);

// ดึง URL ทั้งหมดที่เคยบันทึกไว้ในชีต
const oldLogs = $('Get row(s) in sheet3').all();
const loggedUrls = oldLogs.map(item => item.json.Source_URLs || '').join(' ');

// กรองเอาเฉพาะข่าวที่ URL ยังไม่เคยปรากฏในชีต
const freshNews = $input.all().filter(newsItem => {
  const currentLink = newsItem.json.link || '';
