// 1. ดึง User ID ทั้งหมดจากโหนด Google Sheets (sheet3)
// และคัดเฉพาะ LINE User ID ที่ถูกต้อง (ขึ้นต้นด้วย U และไม่มีค่าข้อความทั่วไปซ้ำ)
const rawUserIds = $("Get row(s) in sheet3").all().map(item => item.json.User_ID || item.json.user_id).filter(Boolean);

const uniqueUserIds = [...new Set(rawUserIds)].filter(id => 
  typeof id === 'string' && id.trim().startsWith('U') && id.trim().length > 20
);

// 2. ถอดรหัสและเตรียมข้อมูลเนื้อหาข่าวจาก AI
let raw = $json.output;
let parsed = {};

if (typeof raw === 'string') {
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      try { parsed = JSON.parse(match[0]); } catch (err) {}
    }
  }
} else if (typeof raw === 'object' && raw !== null) {
  parsed = raw;
}

// ปลดชั้นซ้อน กรณี AI ส่งโครงสร้าง { output: { ... } }
const data = parsed.output || parsed;
const execSummary = data.executive_summary || "";
const newsList = Array.isArray(data.news) ? data.news : [];
const decisionSummary = data.decision_summary || data.business_decision_summary || data.decision_support || "";

// 3. จัดข้อความแจ้งเตือน
let messageText = "🔔 อัปเดตข่าวด่วนรอบ 6 ชั่วโมง\n" + execSummary;

if (newsList.length > 0) {
  messageText += "\n\n" + newsList.map((item, index) => 
    "⚡ " + (index + 1) + ". " + (item.title || "") +
    "\n- สาระสำคัญ:\n" + (item.summary || "") +
    "\n- ที่มา: " + (item.reference_url || item.link || "")
  ).join("\n\n");
}

if (decisionSummary) {
  messageText += "\n\n💡 สรุปเพื่อสนับสนุนการตัดสินใจทางธุรกิจ:\n" + decisionSummary;
}

// 4. ส่งออกข้อมูลเชิงโครงสร้าง Object สำหรับโหนด HTTP Request
return {
  json: {
    "to": uniqueUserIds,
    "messages": [
      {
        "type": "text",
        "text": messageText
      }
    ]
  }
};
